  "speaker.scout": "Scout",
  "speaker.villager": "Miller",
  "dlg.1.pre.0": "Smoke rises from the border outpost. Goblins have come out of the forest!",
  "dlg.1.pre.1": "My ravens counted them: a small pack. More will follow.",
  "dlg.1.pre.2": "Build your towers at the bends of the road. Enemies linger there.",
  "dlg.1.pre.3": "I’ll lay the stones, you give the orders. The outpost will not fall.",
  "dlg.1.post.0": "That was only a vanguard. Something is stirring in the north.",
  "dlg.2.pre.0": "They burned the mill! Wolves in the village, families running to the castle!",
  "dlg.2.pre.1": "Wolves are fast. Let’s greet them with fire. My forge is ready.",
  "dlg.2.pre.2": "The Dragon Forge’s flame clings to its target. A burning pack won’t get far.",
  "dlg.2.post.0": "The villagers are safe. But these raids come too often.",
  "dlg.3.pre.0":
    "My scouts found something: the raids come at the same hour, on the same road. These aren’t stray gangs.",
  "dlg.3.pre.1": "Someone is guiding them. Hold the pass, we’ll work out the rest later.",
  "dlg.3.pre.2": "I woke the frost runes in the pass. When fire meets ice, mist rises.",
  "dlg.3.post.0": "The bandit captain muttered a name before he died. I couldn’t make it out.",
  "dlg.3.post.1": "Their weapons are well forged. This is no bandit work. To the bridge.",
  "enemy.armoredBandit": "Armored Bandit",
  "enemy.armoredBandit.desc": "Heavily armored and tough. Shrugs off half of physical damage; ballistas and magic work.",
  "hud.income": "Income",
  "tut.mine": "Gold markers are mine sites. The Royal Mine produces gold only while a wave is running, so build it early and it pays for itself.",
  "dlg.4.pre.0": "The Stone Bridge is the only crossing. Hold it and the north road is closed.",
  "dlg.4.pre.1": "I found an old ballista overlooking the bridge. It punches straight through armor.",
  "dlg.4.pre.2": "There are old mine shafts on both banks. Dig them and they bring in gold while we fight.",
  "dlg.4.post.0": "Look behind this shield. There was a crest here; someone scratched it off.",
  "dlg.4.post.1": "Bandits don't scratch off their crests. These men serve someone.",
  "enemy.raven": "Black Raven",
  "enemy.raven.desc": "Flies over soldiers and the hero. Dragon Forges and ballistas cannot hit it.",
  "tut.flying": "Flying enemies pass over your soldiers. Archer, Frost and Storm towers can hit them; Dragon Forges and ballistas cannot.",
  "dlg.5.pre.0": "An old storm tower sleeps on this hill. If I wake its runes, lightning will leap from one foe to the next.",
  "dlg.5.pre.1": "The sky is darkening. Ravens are coming, a whole flock of them.",
  "dlg.5.pre.2": "Soldiers can't stop what flies. Build your towers accordingly.",
  "dlg.5.post.0": "These were no ordinary birds. Someone is using them as scouts.",
  "dlg.5.post.1": "Their trail leads to the marsh. The goblin shamans nest there.",
  "enemy.goblinShaman": "Goblin Shaman",
  "enemy.goblinShaman.desc": "Heals nearby enemies every few seconds. Take it down first.",
  "enemy.swampSlime": "Swamp Slime",
  "enemy.swampSlime.desc": "Slow, tough and resistant to magic. Splits into two small slimes when it dies.",
  "enemy.slimeling": "Slimeling",
  "enemy.slimeling.desc": "A piece broken off a Swamp Slime.",
  "dlg.6.pre.0": "The mist is so thick I can barely see my own towers. The shamans are here; they raise their wounded with magic.",
  "dlg.6.pre.1": "I called the eagles down from the mountain. They tear anything that flies out of the sky.",
  "dlg.6.pre.2": "Something is moving in the mud. Cut it and it splits in two. Be careful.",
  "dlg.6.post.0": "A sealed letter was in the shaman's pouch. This seal wasn't scratched off: a red claw.",
  "dlg.6.post.1": "Redclaw. Garrik Redclaw. The old lord of the north. We thought he was in exile.",
  "dlg.7.pre.0": "Garrik's raider camp lies ahead. They are pouring men out of both sides of the palisade.",
  "dlg.7.pre.1": "I've built the Alchemist Tower. Its brew softens armor, and the poison kills slowly but surely.",
  "dlg.7.pre.2": "Fire touching a poisoned foe makes it explode. Build the forge and the alchemist side by side.",
  "dlg.7.post.0": "The camp has fallen. But Garrik isn't here; his men fell back to his keep.",
  "dlg.7.post.1": "Then we go to his keep. This ends there.",
  "enemy.garrik": "Garrik Redclaw",
  "enemy.garrik.desc": "Boss. His war cry gives nearby enemies a shield and a burst of speed.",
  "hud.buff": "Power bonus",
  "hud.rallied": "WAR CRY",
  "dlg.8.pre.0": "Redclaw's keep. Garrik's banner still flies from the battlements.",
  "dlg.8.pre.1": "I woke the old rune stones. Towers you build beside them hit harder.",
  "dlg.8.pre.2": "When Garrik roars, his men raise shields and start running. Turn everything on him in that moment.",
  "dlg.8.post.0": "Garrik has fallen. He laughed as he died: 'I only opened the gate. What comes next comes from Varhol.'",
  "dlg.8.post.1": "Varhol... They said the dead walk beyond the border. I thought it was a tale.",
  "settings.title": "Settings",
